#include "ir.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <errno.h>

static char *dupstr(const char*s){size_t n=strlen(s)+1;char*p=malloc(n);if(p)memcpy(p,s,n);return p;}

static const char *const opcode_names[R6_OP_COUNT] = {
 "nop","load_const","load_var","store_var","decl_var","add","sub","mul","div","mod","eq","ne","lt","le","gt","ge","and_op","or_op","not_op","neg","begin_block","end_block","call","ret","jump","jump_if_false","alloc","free","db_get","db_set","db_all","db_where","http_response","label","copy","arg","load_field","store_field","switch_op","type_info","list_create","list_push","list_get","list_set","list_len","list_pop","map_create","map_set","map_get","map_has","map_delete","map_keys","result_ok","result_err","result_unwrap","result_is_ok","result_unwrap_err","union_create","union_get_tag","union_get_data"
};
const char *r6_opcode_name(R6Opcode op) { return op >= 0 && op < R6_OP_COUNT ? opcode_names[op] : "<invalid>"; }

typedef enum { J_OBJ, J_ARR, J_STR, J_NUM, J_TRUE, J_FALSE, J_NULL } JKind;
typedef struct JNode { JKind kind; size_t line,col,slen; char *s; struct JNode **v; size_t n,cap; } JNode;
typedef struct { const char *p; size_t n,i,line,col; R6Diagnostic *d; } Parser;
static void fail(Parser *p,const char *code,const char *msg) { if (p->d && !p->d->code[0]) { p->d->line=p->line; p->d->column=p->col; snprintf(p->d->code,sizeof p->d->code,"%s",code); snprintf(p->d->message,sizeof p->d->message,"%s",msg); } }
static char peek(Parser *p){return p->i<p->n?p->p[p->i]:0;}
static char take(Parser *p){char c=peek(p);if(c){p->i++;if(c=='\n'){p->line++;p->col=1;}else p->col++;}return c;}
static void ws(Parser *p){while(peek(p)==' '||peek(p)=='\t'||peek(p)=='\r'||peek(p)=='\n')take(p);}
static void jfree(JNode *x){if(!x)return;for(size_t i=0;i<x->n;i++)jfree(x->v[i]);free(x->v);free(x->s);free(x);}
static JNode *node(Parser*p,JKind k){JNode*x=calloc(1,sizeof*x);if(!x){fail(p,"E_MEMORY","out of memory");return NULL;}x->kind=k;x->line=p->line;x->col=p->col;return x;}
static bool push(Parser*p,JNode*x,JNode*y){if(x->n==x->cap){size_t c=x->cap?x->cap*2:4;JNode**v=realloc(x->v,c*sizeof*v);if(!v){fail(p,"E_MEMORY","out of memory");return false;}x->v=v;x->cap=c;}x->v[x->n++]=y;return true;}
static int hexval(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static bool utf8_valid(const unsigned char*s,size_t n){for(size_t i=0;i<n;){unsigned c=s[i++];if(c<0x80)continue;unsigned need=c>=0xC2&&c<=0xDF?1:c>=0xE0&&c<=0xEF?2:c>=0xF0&&c<=0xF4?3:99;if(need==99||i+need>n)return false;unsigned first=s[i];if((c==0xE0&&first<0xA0)||(c==0xED&&first>=0xA0)||(c==0xF0&&first<0x90)||(c==0xF4&&first>=0x90))return false;for(unsigned j=0;j<need;j++)if((s[i++]&0xC0)!=0x80)return false;}return true;}
static bool append_utf8(char*out,size_t*o,unsigned cp){if(cp<=0x7f)out[(*o)++]=(char)cp;else if(cp<=0x7ff){out[(*o)++]=(char)(0xc0|(cp>>6));out[(*o)++]=(char)(0x80|(cp&63));}else if(cp<=0xffff){out[(*o)++]=(char)(0xe0|(cp>>12));out[(*o)++]=(char)(0x80|((cp>>6)&63));out[(*o)++]=(char)(0x80|(cp&63));}else if(cp<=0x10ffff){out[(*o)++]=(char)(0xf0|(cp>>18));out[(*o)++]=(char)(0x80|((cp>>12)&63));out[(*o)++]=(char)(0x80|((cp>>6)&63));out[(*o)++]=(char)(0x80|(cp&63));}else return false;return true;}
static JNode *string_node(Parser*p){JNode*x=node(p,J_STR);if(!x)return NULL;take(p);size_t cap=32,o=0;x->s=malloc(cap);if(!x->s){jfree(x);fail(p,"E_MEMORY","out of memory");return NULL;}while(peek(p)&&peek(p)!='"'){unsigned char c=(unsigned char)take(p);if(c<0x20){fail(p,"E_JSON","control character in string");goto bad;}if(c=='\\'){char e=take(p);switch(e){case '"':case '\\':case '/':c=(unsigned char)e;break;case 'b':c='\b';break;case 'f':c='\f';break;case 'n':c='\n';break;case 'r':c='\r';break;case 't':c='\t';break;case 'u':{unsigned cp=0;for(int k=0;k<4;k++){int h=hexval(take(p));if(h<0){fail(p,"E_JSON","invalid unicode escape");goto bad;}cp=(cp<<4)|(unsigned)h;}if(cp>=0xd800&&cp<=0xdbff){if(take(p)!='\\'||take(p)!='u'){fail(p,"E_JSON","unpaired high surrogate");goto bad;}unsigned lo=0;for(int k=0;k<4;k++){int h=hexval(take(p));if(h<0){fail(p,"E_JSON","invalid low surrogate");goto bad;}lo=(lo<<4)|(unsigned)h;}if(lo<0xdc00||lo>0xdfff){fail(p,"E_JSON","invalid low surrogate");goto bad;}cp=0x10000+((cp-0xd800)<<10)+(lo-0xdc00);}else if(cp>=0xdc00&&cp<=0xdfff){fail(p,"E_JSON","unpaired low surrogate");goto bad;}if(o+4>=cap){cap*=2;char*q=realloc(x->s,cap);if(!q){fail(p,"E_MEMORY","out of memory");goto bad;}x->s=q;}append_utf8(x->s,&o,cp);continue;}default:fail(p,"E_JSON","invalid string escape");goto bad;}}
if(o+5>=cap){cap*=2;char*q=realloc(x->s,cap);if(!q){fail(p,"E_MEMORY","out of memory");goto bad;}x->s=q;}x->s[o++]=(char)c;}if(take(p)!='"'){fail(p,"E_JSON","unterminated string");goto bad;}x->s[o]=0;x->slen=o;if(!utf8_valid((unsigned char*)x->s,o)){fail(p,"E_UTF8","invalid UTF-8 string");goto bad;}return x;bad:jfree(x);return NULL;}
static JNode *value(Parser*p);
static JNode *compound(Parser*p,JKind k){char end=k==J_OBJ?'}':']';take(p);JNode*x=node(p,k);if(!x)return NULL;ws(p);if(peek(p)==end){take(p);return x;}for(;;){if(k==J_OBJ){if(peek(p)!='"'){fail(p,"E_JSON","object key must be a string");goto bad;}JNode*key=string_node(p);if(!key)goto bad;ws(p);if(take(p)!=':'){jfree(key);fail(p,"E_JSON","expected ':'");goto bad;}ws(p);JNode*v=value(p);if(!v||!push(p,x,key)||!push(p,x,v)){jfree(key);jfree(v);goto bad;}}else{JNode*v=value(p);if(!v||!push(p,x,v)){jfree(v);goto bad;}}ws(p);char c=take(p);if(c==end)return x;if(c!=','){fail(p,"E_JSON","expected ',' or closing delimiter");goto bad;}ws(p);}bad:jfree(x);return NULL;}
static JNode *value(Parser*p){ws(p);char c=peek(p);if(c=='{')return compound(p,J_OBJ);if(c=='[')return compound(p,J_ARR);if(c=='"')return string_node(p);JKind k;const char*lit;if(c=='t'){k=J_TRUE;lit="true";}else if(c=='f'){k=J_FALSE;lit="false";}else if(c=='n'){k=J_NULL;lit="null";}else if(c=='-'||(c>='0'&&c<='9')){JNode*x=node(p,J_NUM);size_t st=p->i;if(c=='-')take(p);if(peek(p)=='0'){take(p);if(peek(p)>='0'&&peek(p)<='9'){jfree(x);fail(p,"E_JSON","leading zero in number");return NULL;}}else{if(peek(p)<'1'||peek(p)>'9'){jfree(x);fail(p,"E_JSON","invalid number");return NULL;}while(peek(p)>='0'&&peek(p)<='9')take(p);}while(peek(p)>='0'&&peek(p)<='9')take(p);if(peek(p)=='.'||peek(p)=='e'||peek(p)=='E'){jfree(x);fail(p,"E_JSON","only integer JSON numbers are accepted here");return NULL;}size_t n=p->i-st;x->s=malloc(n+1);if(!x->s){jfree(x);fail(p,"E_MEMORY","out of memory");return NULL;}memcpy(x->s,p->p+st,n);x->s[n]=0;return x;}else{fail(p,"E_JSON","unexpected token");return NULL;}size_t n=strlen(lit);for(size_t i=0;i<n;i++)if(take(p)!=lit[i]){fail(p,"E_JSON","invalid literal");return NULL;}return node(p,k);}
static bool eq(const JNode*x,const char*s){return x&&x->kind==J_STR&&x->slen==strlen(s)&&!memcmp(x->s,s,x->slen);}
static JNode *field(Parser*p,JNode*x,const char*k){if(!x||x->kind!=J_OBJ){fail(p,"E_SCHEMA","expected object");return NULL;}JNode*r=NULL;for(size_t i=0;i<x->n;i+=2)if(eq(x->v[i],k)){if(r){fail(p,"E_DUPLICATE","duplicate object key");return NULL;}r=x->v[i+1];}if(!r){char b[160];snprintf(b,sizeof b,"missing field '%s'",k);fail(p,"E_SCHEMA",b);}return r;}
static bool exact(Parser*p,JNode*x,const char*const*keys,size_t n){if(!x||x->kind!=J_OBJ){fail(p,"E_SCHEMA","expected object");return false;}for(size_t i=0;i<x->n;i+=2){for(size_t j=0;j<i;j+=2)if(x->v[i]->kind==J_STR&&x->v[j]->kind==J_STR&&!strcmp(x->v[i]->s,x->v[j]->s)){fail(p,"E_DUPLICATE","duplicate object key");return false;}bool found=false;for(size_t j=0;j<n;j++)if(eq(x->v[i],keys[j]))found=true;if(!found){fail(p,"E_SCHEMA","unexpected object key");return false;}}for(size_t j=0;j<n;j++){bool found=false;for(size_t i=0;i<x->n;i+=2)if(eq(x->v[i],keys[j]))found=true;if(!found){fail(p,"E_SCHEMA","required object key missing");return false;}}return true;}
static bool arr(Parser*p,JNode*x){if(!x||x->kind!=J_ARR){fail(p,"E_SCHEMA","expected array");return false;}return true;}
static bool str(Parser*p,JNode*x,char**out){if(!x||x->kind!=J_STR){fail(p,"E_SCHEMA","expected string");return false;}*out=dupstr(x->s);if(!*out){fail(p,"E_MEMORY","out of memory");return false;}return true;}
static bool number(Parser*p,JNode*x,int64_t lo,int64_t hi,int64_t*out){if(!x||x->kind!=J_NUM){fail(p,"E_SCHEMA","expected integer");return false;}char*end;errno=0;long long n=strtoll(x->s,&end,10);if(errno||*end||n<lo||n>hi){fail(p,"E_RANGE","integer outside allowed range");return false;}*out=n;return true;}
static bool boolean(Parser*p,JNode*x,bool*out){if(x&&x->kind==J_TRUE){*out=true;return true;}if(x&&x->kind==J_FALSE){*out=false;return true;}fail(p,"E_SCHEMA","expected boolean");return false;}
static bool parse_value(Parser*p,JNode*x,R6Value*out){static const char*const tags[]={"int","float64_bits","string","symbol","bool","reg","label","none"};if(!x||x->kind!=J_OBJ||x->n!=2){fail(p,"E_SCHEMA","value must be a one-tag object");return false;}JNode*k=x->v[0],*v=x->v[1];for(size_t i=0;i<8;i++)if(eq(k,tags[i])){int64_t z;out->kind=(R6ValueKind)(i==0?R6_VAL_INT:i==1?R6_VAL_FLOAT64:i==2?R6_VAL_STRING:i==3?R6_VAL_SYMBOL:i==4?R6_VAL_BOOL:i==5?R6_VAL_REG:i==6?R6_VAL_LABEL:R6_VAL_NONE);switch(i){case 0:if(!v||v->kind!=J_STR){fail(p,"E_SCHEMA","int literal must be decimal string");return false;}if(v->s[0]=='+'||!v->s[0]){fail(p,"E_SCHEMA","invalid decimal int literal");return false;} {char*end;errno=0;long long q=strtoll(v->s,&end,10);if(errno||*end||q<INT32_MIN||q>INT32_MAX){fail(p,"E_RANGE","int literal outside int32 range");return false;}out->as.i32=(int32_t)q;}break;case 1:if(!v||v->kind!=J_STR||strlen(v->s)!=16){fail(p,"E_SCHEMA","float64_bits must contain 16 hex digits");return false;}out->as.f64_bits=0;for(int j=0;j<16;j++){int h=hexval(v->s[j]);if(h<0||(v->s[j]>='A'&&v->s[j]<='F')){fail(p,"E_SCHEMA","float64_bits must be lowercase hexadecimal");return false;}out->as.f64_bits=(out->as.f64_bits<<4)|(unsigned)h;}break;case 2:case 3:if(!v||v->kind!=J_STR){fail(p,"E_SCHEMA","expected string value");return false;}out->as.string=malloc(v->slen+1);if(!out->as.string){fail(p,"E_MEMORY","out of memory");return false;}memcpy(out->as.string,v->s,v->slen+1);out->string_len=v->slen;break;case 4:return boolean(p,v,&out->as.boolean);case 5:case 6:if(!number(p,v,0,INT32_MAX,&z))return false;out->as.i32=(int32_t)z;break;case 7:if(!v||v->kind!=J_NULL){fail(p,"E_SCHEMA","none value must be null");return false;}break;}return true;}fail(p,"E_SCHEMA","unknown value tag");return false;}


static bool strings(Parser*p,JNode*x,char***out,size_t*count){if(!arr(p,x))return false;*count=x->n;*out=calloc(x->n?x->n:1,sizeof(char*));if(!*out){fail(p,"E_MEMORY","out of memory");return false;}for(size_t i=0;i<x->n;i++)if(!str(p,x->v[i],&(*out)[i]))return false;return true;}
static bool parse_route(Parser*p,JNode*x,R6Function*f){if(x->kind==J_NULL)return true;static const char*const keys[]={"method","path","has_limit","limit_rate","limit_window_ms","limit_burst"};if(!exact(p,x,keys,6))return false;int64_t z;if(!str(p,field(p,x,"method"),&f->route.method)||!str(p,field(p,x,"path"),&f->route.path)||!boolean(p,field(p,x,"has_limit"),&f->route.has_limit)||!number(p,field(p,x,"limit_rate"),INT64_MIN,INT64_MAX,&f->route.limit_rate)||!number(p,field(p,x,"limit_window_ms"),INT64_MIN,INT64_MAX,&f->route.limit_window_ms)||!number(p,field(p,x,"limit_burst"),INT64_MIN,INT64_MAX,&f->route.limit_burst))return false;(void)z;f->has_route=true;return true;}
static bool parse_instruction(Parser*p,JNode*x,R6Instruction*i){static const char*const keys[]={"op","dest","operands","elem_kind"};if(!exact(p,x,keys,4))return false;char*op=NULL;int64_t z;if(!str(p,field(p,x,"op"),&op))return false;int found=-1;for(int k=0;k<R6_OP_COUNT;k++)if(!strcmp(op,opcode_names[k]))found=k;if(found<0){fail(p,"E_OPCODE","opcode is not in IRv1");free(op);return false;}free(op);i->opcode=(R6Opcode)found;JNode*d=field(p,x,"dest");if(d->kind!=J_NULL){if(!number(p,d,0,INT32_MAX,&z))return false;i->has_dest=true;i->dest=(int32_t)z;}JNode*a=field(p,x,"operands");if(!arr(p,a)||a->n!=3){fail(p,"E_SCHEMA","operands must contain exactly three values");return false;}for(int k=0;k<3;k++)if(!parse_value(p,a->v[k],&i->operands[k]))return false;if(!number(p,field(p,x,"elem_kind"),0,5,&z))return false;i->elem_kind=(int32_t)z;i->line=x->line;i->column=x->col;return true;}
static bool parse_function(Parser*p,JNode*x,R6Function*f){static const char*const keys[]={"name","params","param_types","instructions","register_count","register_types","return_type","extern","route"};if(!exact(p,x,keys,9))return false;if(!str(p,field(p,x,"name"),&f->name)||!strings(p,field(p,x,"params"),&f->params,&f->param_count)||!strings(p,field(p,x,"param_types"),&f->param_types,&(size_t){0}))return false;JNode*pt=field(p,x,"param_types");if(pt->n!=f->param_count){fail(p,"E_SCHEMA","params and param_types length mismatch");return false;}if(!arr(p,field(p,x,"instructions")))return false;JNode*ins=field(p,x,"instructions");f->instruction_count=ins->n;f->instructions=calloc(ins->n?ins->n:1,sizeof* f->instructions);if(!f->instructions){fail(p,"E_MEMORY","out of memory");return false;}for(size_t k=0;k<ins->n;k++)if(!parse_instruction(p,ins->v[k],&f->instructions[k]))return false;int64_t z;if(!number(p,field(p,x,"register_count"),0,INT32_MAX,&z))return false;f->register_count=(int32_t)z;if(!strings(p,field(p,x,"register_types"),&f->register_types,&f->register_type_count))return false;if(f->register_type_count!=(size_t)f->register_count){fail(p,"E_SCHEMA","register_count and register_types length mismatch");return false;}if(!str(p,field(p,x,"return_type"),&f->return_type)||!boolean(p,field(p,x,"extern"),&f->is_extern)||!parse_route(p,field(p,x,"route"),f))return false;return true;}
static bool parse_model(Parser*p,JNode*x,R6Model*m){static const char*const keys[]={"name","fields","type_params"};static const char*const fk[]={"name","type_name"};if(!exact(p,x,keys,3)||!str(p,field(p,x,"name"),&m->name))return false;JNode*fs=field(p,x,"fields");if(!arr(p,fs))return false;m->field_count=fs->n;m->fields=calloc(fs->n?fs->n:1,sizeof*m->fields);if(!m->fields){fail(p,"E_MEMORY","out of memory");return false;}for(size_t i=0;i<fs->n;i++){JNode*y=fs->v[i];if(!exact(p,y,fk,2)||!str(p,field(p,y,"name"),&m->fields[i].name)||!str(p,field(p,y,"type_name"),&m->fields[i].type_name))return false;}if(!strings(p,field(p,x,"type_params"),&m->type_params,&m->type_param_count))return false;if(m->type_param_count){fail(p,"E_UNSPECIFIED","generic model parameters are UNSPECIFIED");return false;}return true;}
static bool parse_type(Parser*p,JNode*x,R6Type*t){static const char*const keys[]={"name","kind","variants","rich_variants","methods"};if(!exact(p,x,keys,5)||!str(p,field(p,x,"name"),&t->name)||!str(p,field(p,x,"kind"),&t->kind)||!strings(p,field(p,x,"variants"),&t->variants,&t->variant_count)||!strings(p,field(p,x,"rich_variants"),&t->rich_variants,&t->rich_variant_count)||!strings(p,field(p,x,"methods"),&t->methods,&t->method_count))return false;if(t->method_count){fail(p,"E_UNSPECIFIED","type methods are UNSPECIFIED");return false;}return true;}
static bool parse_global(Parser*p,JNode*x,R6Global*g){static const char*const keys[]={"name","value","type_name"};if(!exact(p,x,keys,3)||!str(p,field(p,x,"name"),&g->name)||!parse_value(p,field(p,x,"value"),&g->value)||!str(p,field(p,x,"type_name"),&g->type_name))return false;return true;}
static bool parse_module(Parser*p,JNode*x,R6Module*m){static const char*const keys[]={"functions","globals","models","types","migrations"};if(!exact(p,x,keys,5))return false;JNode*a=field(p,x,"functions");if(!arr(p,a))return false;m->function_count=a->n;m->functions=calloc(a->n?a->n:1,sizeof*m->functions);if(!m->functions){fail(p,"E_MEMORY","out of memory");return false;}for(size_t i=0;i<a->n;i++)if(!parse_function(p,a->v[i],&m->functions[i]))return false;a=field(p,x,"globals");if(!arr(p,a))return false;m->global_count=a->n;m->globals=calloc(a->n?a->n:1,sizeof*m->globals);if(!m->globals){fail(p,"E_MEMORY","out of memory");return false;}for(size_t i=0;i<a->n;i++)if(!parse_global(p,a->v[i],&m->globals[i]))return false;a=field(p,x,"models");if(!arr(p,a))return false;m->model_count=a->n;m->models=calloc(a->n?a->n:1,sizeof*m->models);if(!m->models){fail(p,"E_MEMORY","out of memory");return false;}for(size_t i=0;i<a->n;i++)if(!parse_model(p,a->v[i],&m->models[i]))return false;a=field(p,x,"types");if(!arr(p,a))return false;m->type_count=a->n;m->types=calloc(a->n?a->n:1,sizeof*m->types);if(!m->types){fail(p,"E_MEMORY","out of memory");return false;}for(size_t i=0;i<a->n;i++)if(!parse_type(p,a->v[i],&m->types[i]))return false;if(!strings(p,field(p,x,"migrations"),&m->migrations,&m->migration_count))return false;return true;}
static bool validate(Parser*p,R6Module*m){for(size_t i=0;i<m->function_count;i++)for(size_t j=0;j<i;j++)if(!strcmp(m->functions[i].name,m->functions[j].name)){fail(p,"E_DUPLICATE","duplicate function name");return false;}for(size_t i=0;i<m->global_count;i++)for(size_t j=0;j<i;j++)if(!strcmp(m->globals[i].name,m->globals[j].name)){fail(p,"E_DUPLICATE","duplicate global name");return false;}for(size_t f=0;f<m->function_count;f++){R6Function*x=&m->functions[f];for(size_t i=0;i<x->instruction_count;i++){R6Instruction*y=&x->instructions[i];if(!(y->opcode==R6_OP_LOAD_CONST||y->opcode==R6_OP_LOAD_VAR||y->opcode==R6_OP_DECL_VAR||y->opcode==R6_OP_STORE_VAR||y->opcode==R6_OP_ADD||y->opcode==R6_OP_SUB||y->opcode==R6_OP_MUL||y->opcode==R6_OP_DIV||y->opcode==R6_OP_MOD||y->opcode==R6_OP_EQ||y->opcode==R6_OP_NE||y->opcode==R6_OP_LT||y->opcode==R6_OP_LE||y->opcode==R6_OP_GT||y->opcode==R6_OP_GE||y->opcode==R6_OP_AND_OP||y->opcode==R6_OP_OR_OP||y->opcode==R6_OP_NOT_OP||y->opcode==R6_OP_NEG||y->opcode==R6_OP_COPY||y->opcode==R6_OP_JUMP||y->opcode==R6_OP_JUMP_IF_FALSE||y->opcode==R6_OP_LABEL||y->opcode==R6_OP_ARG||y->opcode==R6_OP_CALL||y->opcode==R6_OP_RET||y->opcode==R6_OP_LIST_CREATE||y->opcode==R6_OP_LIST_PUSH||y->opcode==R6_OP_LIST_LEN||y->opcode==R6_OP_LIST_GET)){fail(p,"E_UNSUPPORTED","opcode is outside the current supported range");return false;}if(y->has_dest&&y->dest>=x->register_count){fail(p,"E_RANGE","instruction destination register out of range");return false;}for(int a=0;a<3;a++)if(y->operands[a].kind==R6_VAL_REG&&y->operands[a].as.i32>=x->register_count){fail(p,"E_RANGE","operand register out of range");return false;}if(y->opcode==R6_OP_LABEL)for(size_t j=0;j<i;j++)if(x->instructions[j].opcode==R6_OP_LABEL&&x->instructions[j].operands[0].as.i32==y->operands[0].as.i32){fail(p,"E_DUPLICATE","duplicate label in function");return false;}if(y->elem_kind&&!(y->opcode>=R6_OP_LIST_CREATE&&y->opcode<=R6_OP_LIST_POP)){fail(p,"E_SCHEMA","elem_kind only allowed on list opcodes");return false;}}}return true;}
void r6_module_free(R6Module*m){if(!m)return;for(size_t f=0;f<m->function_count;f++){R6Function*x=&m->functions[f];free(x->name);for(size_t i=0;i<x->param_count;i++){free(x->params[i]);free(x->param_types[i]);}free(x->params);free(x->param_types);for(size_t i=0;i<x->instruction_count;i++)for(int a=0;a<3;a++)if(x->instructions[i].operands[a].kind==R6_VAL_STRING||x->instructions[i].operands[a].kind==R6_VAL_SYMBOL)free(x->instructions[i].operands[a].as.string);free(x->instructions);for(size_t i=0;i<x->register_type_count;i++)free(x->register_types[i]);free(x->register_types);free(x->return_type);free(x->route.method);free(x->route.path);}free(m->functions);for(size_t i=0;i<m->global_count;i++){free(m->globals[i].name);free(m->globals[i].type_name);if(m->globals[i].value.kind==R6_VAL_STRING||m->globals[i].value.kind==R6_VAL_SYMBOL)free(m->globals[i].value.as.string);}free(m->globals);for(size_t i=0;i<m->model_count;i++){free(m->models[i].name);for(size_t j=0;j<m->models[i].field_count;j++){free(m->models[i].fields[j].name);free(m->models[i].fields[j].type_name);}free(m->models[i].fields);for(size_t j=0;j<m->models[i].type_param_count;j++)free(m->models[i].type_params[j]);free(m->models[i].type_params);}free(m->models);for(size_t i=0;i<m->type_count;i++){R6Type*t=&m->types[i];free(t->name);free(t->kind);for(size_t j=0;j<t->variant_count;j++)free(t->variants[j]);for(size_t j=0;j<t->rich_variant_count;j++)free(t->rich_variants[j]);for(size_t j=0;j<t->method_count;j++)free(t->methods[j]);free(t->variants);free(t->rich_variants);free(t->methods);}free(m->types);for(size_t i=0;i<m->migration_count;i++)free(m->migrations[i]);free(m->migrations);memset(m,0,sizeof*m);}
bool r6_ir_parse(const char*data,size_t length,R6Module*out,R6Diagnostic*d){if(!out||(!data&&length))return false;memset(out,0,sizeof*out);if(d)memset(d,0,sizeof*d);Parser p={data,length,0,1,1,d};if(!length||data[length-1]!='\n'){fail(&p,"E_JSON","document must end with LF");return false;}if(length>=3&&(unsigned char)data[0]==0xef&&(unsigned char)data[1]==0xbb&&(unsigned char)data[2]==0xbf){fail(&p,"E_JSON","UTF-8 BOM is not allowed");return false;}JNode*root=value(&p);if(root){ws(&p);if(p.i!=p.n){fail(&p,"E_JSON","trailing bytes after root value");jfree(root);root=NULL;}}if(!root)return false;static const char*const rk[]={"format","version","module"};bool ok=exact(&p,root,rk,3);if(ok&&!eq(field(&p,root,"format"),"orbit-ir")){fail(&p,"E_FORMAT","format must be orbit-ir");ok=false;}int64_t version;if(ok&&!number(&p,field(&p,root,"version"),INT64_MIN,INT64_MAX,&version))ok=false;if(ok&&version!=1){fail(&p,"E_VERSION","unsupported IR version (R6 supports version 1)");ok=false;}if(ok)ok=parse_module(&p,field(&p,root,"module"),out);if(ok)ok=validate(&p,out);jfree(root);if(!ok)r6_module_free(out);return ok;}
